    "detailed_explanation": "顕著な普遍的価値（Outstanding Universal Value / OUV）は世界遺産条約の核心概念です。OUVの声明（Statement of OUV：SoOUV）は各登録遺産について世界遺産委員会が採択します。古い登録遺産については遡及的にSoOUVを策定する作業が継続中です。OUVの要件は3つ：①登録基準((i)〜(x))の少なくとも1つを満たす、②真正性（Authenticity）の条件を満たす（文化遺産）、③完全性（Integrity）の条件を満たす。真正性とは形状・素材・機能・伝統等の面で変化なく保たれていること。完全性とは価値を体現する要素が揃っていること。OUVは登録後も追加登録基準の採択等で変更される場合があります。",
