    "detailed_explanation": "危機にさらされている世界遺産リスト（List of World Heritage in Danger）の特徴：①委員会は締約国の同意なしに独自判断で記載可能（条約第11条4項）。②記載後は世界遺産基金からの国際的支援・技術援助を受けられる（支援停止は誤り）。③記載は永続的でなく、保全状況の改善により解除される（例：オマーンのアラビアオリックスの保護区・アゼルバイジャンのワタン城等）。④保全状況が著しく悪化した場合は世界遺産リストから削除される（例：オマーンのアラビアオリックス保護区2007年、ドレスデンのエルベ渓谷2009年）。現在（2025年時点）で約50件が危機遺産リストに記載されています。",
