    "detailed_explanation": "緩衝地帯（バッファゾーン）の特徴：①目的は核心地域（コアゾーン、登録地域）の保護を補完すること。②運用指針は「適切な場合」に設定を強く推奨するが義務ではなく、設定がなくても登録可能な場合がある（例：都市中心部の遺産）。③バッファゾーン内での開発・土地利用の変更は世界遺産委員会への報告が必要。④バッファゾーンの範囲変更はWorld Heritage Committee通知（軽微な修正）または正式推薦書の再提出が必要。⑤保護の根拠は当該国の国内法（世界遺産条約は直接の法的強制力を持たない）。核心地域の保護強度がより重要で、バッファゾーンは補完的役割です。",
