    "detailed_explanation": "シリアル推薦（Serial Nomination）：OUVの証明に必要な複数の構成資産を一括して一つの世界遺産として推薦する方式。例：明治日本の産業革命遺産（23資産・8県）、ル・コルビュジエ建築（7か国17資産）、古都京都の文化財（17資産）。資産間に必ずしも地理的な連続性は不要だが、テーマ的な一貫性が必要。トランスバウンダリー推薦（Transboundary Nomination）：複数の国家の国境をまたいで位置する遺産の推薦。例：コンゴ盆地（複数国）、バイカル湖に隣接するトランスバウンダリー遺産。両方を同時に満たすケースもあります（ル・コルビュジエは7か国のシリアル推薦＋トランスバウンダリー）。",
