    "detailed_explanation": "ウルル・カタジュタ国立公園（オーストラリア、1987年文化的景観に改訂、基準(v)(vi)）：1985年にオーストラリア政府がアボリジニの人々（アナング族）に土地を返還し、国立公園を逆リースする形で運営。アナング族にとってウルルは創世の物語（ドリームタイム）に基づく神聖な岩山で、登山は信仰上禁止されていましたが、観光客は長年無視して登山していました。2019年10月26日より一般観光客の登山が恒久禁止となりました。世界遺産と先住民族の権利をめぐる問題：管理への参加・入場料収入の配分・神聖な場所の情報公開制限等が議論されています。沖ノ島（日本）も「神宿る島」として一般上陸禁止という類似の事例です。",
