    "detailed_explanation": "グレート・バリア・リーフ（オーストラリア、1981年登録）は地球温暖化による海水温上昇が最大の脅威です。水温が平年より1〜2℃高い状態が続くとサンゴが共生藻（褐虫藻）を放出して白化し、そのまま回復しなければ死滅します。2016・2017年に過去最大規模の大規模白化現象が発生し、北部のサンゴの50%以上が死滅。2020・2022年にも大規模白化が起きており、繰り返す白化による累積的なダメージが深刻です。WHCは繰り返し「危機遺産（危機にさらされている世界遺産リスト）」への記載を提案しましたが、オーストラリア政府の強い反対（観光業等への影響懸念）で未記載のままです。オニヒトデも深刻な脅威ですが、最大の問題は温暖化です（選択肢D誤り）。海洋酸性化（pH低下）はあるが「上昇」は誤り（選択肢C誤り）。",
