    "detailed_explanation": "ガラパゴス諸島（エクアドル、1978年登録）固有のウミイグアナ（学名：Amblyrhynchus cristatus）は、世界で唯一海中に潜って餌を採食するトカゲです。主に海底の岩に付着した緑藻・紅藻を食べ、潜水深度は約10m・潜水時間は最大30〜60分に達します。体温調節のために陸上で日光浴をした後に海に入る変温動物です（選択肢Cは「哺乳類に最も近い」が誤り）。固有種であり外来種ではありません（選択肢B誤り）。体色は繁殖期に赤・緑の斑が現れる個体（特にエスパニョーラ島等）もあり、島によって色彩変異があります（選択肢D誤り）。ダーウィンは「最も醜い生き物」と評しましたが、独自の適応進化の見事な例です。",
