    "short_explanation": "グランドプリズマティックスプリングの虹色は水温帯ごとに異なる好熱性微生物の色。中心部（高温・約87℃）は微生物が少なく青く、外縁部はオレンジ・黄の好熱菌が密集します。",
    "detailed_explanation": "イエローストーン国立公園（アメリカ、1978年登録）のグランド・プリズマティック・スプリング（直径約90m）の鮮やかな色彩は、水温帯ごとに異なる好熱性微生物群集によるものです。中心部（約87℃）は高温すぎて微生物がほとんどいないため、水自体の青色が見えます。外縁に向かって水温が下がるにつれ、黄色・橙色・褐色の好熱性シアノバクテリアや藻類が層状に分布し、それぞれの色素（カロテノイドなど）が外縁の鮮やかな色を作り出します。イエローストーンは超巨大火山（カルデラ）の上に位置し、2万以上の熱水地形（間欠泉・温泉・泥沸泉）があります。オールドフェイスフル間欠泉とともに最も有名な景観です。",
